package com.drogaria.backend.service;
import com.drogaria.backend.dto.LojaRequest; import com.drogaria.backend.entity.Loja; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.LojaRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class LojaService { private final LojaRepository r; public LojaService(LojaRepository r){this.r=r;} public List<Loja> listar(){return r.findAll();} public Loja buscar(Integer id){return r.findById(id).orElseThrow(()->new ApiException("Loja nao encontrada",HttpStatus.NOT_FOUND));} public Loja salvar(LojaRequest x){Loja l=new Loja();preencher(l,x);return r.save(l);} public Loja atualizar(Integer id,LojaRequest x){Loja l=buscar(id);preencher(l,x);return r.save(l);} private void preencher(Loja l,LojaRequest x){l.setNome(x.getNome());l.setTelefone(x.getTelefone());l.setHorarioFuncionamento(x.getHorarioFuncionamento());l.setLatitude(x.getLatitude());l.setLongitude(x.getLongitude());} public void excluir(Integer id){r.deleteById(id);} }